pub(crate) fn functionlinearmodelMatlab(mut in_txt: Tpl::Text, mut in_a_modelInfo: SimCode::ModelInfo, mut in_a_modelNamePrefix: ArcStr) -> Result<Tpl::Text> {
    let mut out_txt: Tpl::Text;
    out_txt = (match (in_txt, in_a_modelInfo, in_a_modelNamePrefix) {
        (mut txt, SimCode::ModelInfo { varInfo: SimCode::VarInfo { numStateVars: mut i_varInfo_numStateVars, numInVars: mut i_varInfo_numInVars, numOutVars: mut i_varInfo_numOutVars, .. }, vars: SimCodeVar::SimVars { stateVars: ref i_vars_stateVars, inputVars: ref i_vars_inputVars, outputVars: ref i_vars_outputVars, .. }, .. }, mut a_modelNamePrefix) => {
            let mut l_matrixD: Tpl::Text;
            let mut l_matrixC: Tpl::Text;
            let mut l_matrixB: Tpl::Text;
            let mut l_matrixA: Tpl::Text;
            l_matrixA = genMatrixMatlab(Tpl::emptyTxt.clone(), (literal!("A")).clone(), (literal!("n")).clone(), (literal!("n")).clone(), i_varInfo_numStateVars.clone(), i_varInfo_numStateVars.clone())?;
            l_matrixB = genMatrixMatlab(Tpl::emptyTxt.clone(), (literal!("B")).clone(), (literal!("n")).clone(), (literal!("m")).clone(), i_varInfo_numStateVars.clone(), i_varInfo_numInVars.clone())?;
            l_matrixC = genMatrixMatlab(Tpl::emptyTxt.clone(), (literal!("C")).clone(), (literal!("p")).clone(), (literal!("n")).clone(), i_varInfo_numOutVars.clone(), i_varInfo_numStateVars.clone())?;
            l_matrixD = genMatrixMatlab(Tpl::emptyTxt.clone(), (literal!("D")).clone(), (literal!("p")).clone(), (literal!("m")).clone(), i_varInfo_numOutVars.clone(), i_varInfo_numInVars.clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("const char *")).clone() }))?;
            txt = CodegenUtil::symbolName(txt.clone(), (a_modelNamePrefix.clone()).clone(), (literal!("linear_model_frame")).clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("()\n")).clone(), (literal!("{\n")).clone(), (literal!("  return \"function [A, B, C, D, stateVars, inputVars, outputVars] = linearized_model()\\n\"\n")).clone()], lastHasNewLine: true }))?;
            txt = Tpl::pushBlock(txt.clone(), Arc::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("\"%% ")).clone() }))?;
            txt = Tpl::writeStr(txt.clone(), (a_modelNamePrefix.clone()).clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("\\n\"\n")).clone(), (literal!("\"%% der(x) = A * x + B * u\\n\"\n")).clone(), (literal!("\"%% y = C * x + D * u\\n\"\n")).clone(), (literal!("\"  n = ")).clone()], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt.clone(), (intString(i_varInfo_numStateVars.clone())).clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("; %% number of states\\n\"\n")).clone(), (literal!("\"  m = ")).clone()], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt.clone(), (intString(i_varInfo_numInVars.clone())).clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("; %% number of inputs\\n\"\n")).clone(), (literal!("\"  p = ")).clone()], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt.clone(), (intString(i_varInfo_numOutVars.clone())).clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("; %% number of outputs\\n\"\n")).clone(), (literal!("\"\\n\"\n")).clone(), (literal!("\"  x0 = %s;\\n\"\n")).clone(), (literal!("\"  u0 = %s;\\n\"\n")).clone(), (literal!("\"\\n\"\n")).clone()], lastHasNewLine: true }))?;
            txt = Tpl::writeText(txt.clone(), l_matrixA)?;
            txt = Tpl::softNewLine(txt.clone())?;
            txt = Tpl::writeText(txt.clone(), l_matrixB)?;
            txt = Tpl::softNewLine(txt.clone())?;
            txt = Tpl::writeText(txt.clone(), l_matrixC)?;
            txt = Tpl::softNewLine(txt.clone())?;
            txt = Tpl::writeText(txt.clone(), l_matrixD)?;
            txt = Tpl::softNewLine(txt.clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("\"  stateVars  = {")).clone() }))?;
            txt = getVarNameMatlab(txt.clone(), i_vars_stateVars.clone(), (literal!("x0")).clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("};\\n\"\n")).clone(), (literal!("\"  inputVars  = {")).clone()], lastHasNewLine: false }))?;
            txt = getVarNameMatlab(txt.clone(), i_vars_inputVars.clone(), (literal!("u0")).clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("};\\n\"\n")).clone(), (literal!("\"  outputVars = {")).clone()], lastHasNewLine: false }))?;
            txt = getVarNameMatlab(txt.clone(), i_vars_outputVars.clone(), (literal!("y0")).clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("};\\n\"\n")).clone(), (literal!("\"  Ts = %g; %% stop time\\n\\n\"\n")).clone(), (literal!("\"end\";\n")).clone()], lastHasNewLine: true }))?;
            txt = Tpl::popBlock(txt.clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("}\n")).clone(), (literal!("const char *")).clone()], lastHasNewLine: false }))?;
            txt = CodegenUtil::symbolName(txt.clone(), (a_modelNamePrefix.clone()).clone(), (literal!("linear_model_datarecovery_frame")).clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("()\n")).clone(), (literal!("{\n")).clone(), (literal!("  errorStreamPrint(OMC_LOG_STDOUT, 0, \"Linearization with data recovery not implemented for Matlab.\");\n")).clone(), (literal!("  return \"\";\n")).clone(), (literal!("}")).clone()], lastHasNewLine: false }))?;
            txt.clone()
        },
        (mut txt, _, _) => {
            txt.clone()
        },
    });
    Ok(out_txt)
}

